'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Stage, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './stage.css'
// The shared press and action-type rules the launch and close controls wear.
import './gamestage-primitives.css'
import { LabelFitDefaults } from './label-fit'
import { useStrings, type StringsOverrides } from './strings'
import { CrossGlyph } from './glyphs'
import { FIXED_FITS, StageFitProvider, type StageFit } from './fit'

/**
 * Stage: Gamestage UI arranged around a scene the host owns.
 *
 * The scene is a Three.js canvas, a Unity build, a video, a static image or
 * somebody else's embed (BDS-032). `stage` never renders it, never reaches into
 * it, never measures it and never assumes it exists. It receives it as a node
 * and puts it on the page untouched.
 *
 * Three decisions carry the whole component.
 *
 * **The scene is in normal flow; everything else is absolute over it.** A stage
 * that set its own width or height would fight every host that embeds it, so it
 * sets neither. Instead the scene layer is an ordinary block, which means the
 * scene gives the stage its box, the way an `<img>` gives a figure its box. A
 * stage with no scene is exactly as tall as the host's container makes it, and
 * that is the host's business.
 *
 * **A layer is sized by what is in it unless it is meant to cover.** A `hud` or
 * a `nav` given a placement is pinned to that edge and is as big as its
 * contents; `behind`, `overlay`, `celebration`, anything with no placement and
 * anything placed `center` covers the stage. That distinction is what makes the
 * pointer rule expressible: a layer only takes presses over the area it
 * actually occupies, so a HUD in the corner does not swallow a tap meant for
 * the middle of the scene.
 *
 * **Presses fall through by default over the scene.** Every covering layer is
 * `data-gs-pointer-events="none"` unless the host says otherwise, and the scene layer
 * is always `auto`, because it is the host's and the library does not get to
 * decide how it is operated.
 */

/**
 * The closed set from the attribute contract, bottom to top. An eighth would
 * break the order. `interaction` is the choice grid, slider or form the player
 * answers with: it sits directly above the nav and takes presses, which is why
 * it is not `overlay`, the pointer-none layer the grid used to be put in.
 */
export type StageLayerName = 'scene' | 'behind' | 'hud' | 'interaction' | 'overlay' | 'nav' | 'celebration'

export type StagePlacement =
  | 'top'
  | 'bottom'
  | 'left'
  | 'right'
  | 'center'
  | 'top-left'
  | 'top-right'
  | 'bottom-left'
  | 'bottom-right'

export interface StageLayerProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Which compositing layer this is. Decides the stacking order and nothing else. */
  layer: StageLayerName
  /** Where it sits in the stage. Ignored by layers that cover the whole stage. */
  placement?: StagePlacement
  /**
   * Whether presses land here or fall through to the scene. Defaults to `none`
   * for any layer that covers the stage and `auto` for one sized by its own
   * contents, which is the rule rather than a preference: a full-bleed layer
   * taking presses is the bug the attribute exists to make assertable. A layer
   * covers when it is `behind`, `overlay` or `celebration`, when it is given no
   * placement, or when it is placed `center`. `interaction` never covers: it is
   * pinned to the bottom above the nav and sized by its contents.
   */
  pointer?: 'none' | 'auto'
}

/** The layers that always cover the stage rather than sitting at an edge of it. */
const ALWAYS_COVERING: ReadonlySet<StageLayerName> = new Set(['behind', 'overlay', 'celebration'])

/**
 * Whether a layer covers the stage, which is what decides the pointer default.
 *
 * This is derived from the placement and not from the layer's name, and the
 * difference is a real bug rather than a nicety. A `hud` with no placement
 * keeps all four insets and covers the whole stage, and so does anything
 * placed `center`, which is the one placement that spans by design. Keying the
 * default on the name alone shipped a documented, supported configuration,
 * `<Stage.Layer layer="hud">` with no placement, that declared
 * `data-gs-pointer-events="auto"` across the entire scene and swallowed every press
 * meant for it.
 *
 * So there is one rule: a layer that covers takes no presses unless the host
 * insists, and a layer that is only as big as its contents may take them,
 * whatever it is called.
 */
function coversTheStage(layer: StageLayerName, placement?: StagePlacement) {
  if (layer === 'scene') return false
  // The interaction layer has one place, the bottom, whatever placement it is
  // given, and is only ever as tall as what is in it (at most
  // `--gs-stage-interaction-max`, 40% of the stage by default), so it never
  // covers and always takes the presses it exists for.
  if (layer === 'interaction') return false
  if (ALWAYS_COVERING.has(layer)) return true
  return placement === undefined || placement === 'center'
}

/**
 * One layer of the stage. Exported on its own as well as reachable through
 * `Stage.Layer`, because a host composing layers in a loop needs the component
 * and not the property.
 */
export function StageLayer({
  layer,
  placement,
  pointer,
  className,
  children,
  ...rest
}: StageLayerProps) {
  // The scene is the host's, so the library never takes its presses away. A
  // layer that covers passes them through unless the host asks for them. An
  // edge-pinned one takes them, and can afford to, because it is only as large
  // as what is in it.
  const takesPresses = pointer ?? (coversTheStage(layer, placement) ? 'none' : 'auto')

  return (
    <div
      {...rest}
      className={['gs-stage__layer', className].filter(Boolean).join(' ')}
      data-gs-layer={layer}
      data-gs-placement={layer === 'scene' ? undefined : placement}
      data-gs-pointer-events={layer === 'scene' ? 'auto' : takesPresses}
    >
      {children}
    </div>
  )
}

export interface StageProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /**
   * The host's scene, rendered untouched into the scene layer. Any node: a
   * canvas, a video, an image, an iframe. The stage does not read it, size it
   * or style it, and omitting it is a supported case, because a quiz with no
   * scene uses the same components as a Unity build.
   */
  scene?: React.ReactNode
  /**
   * Where the library's layers sit relative to the scene. The host declares it;
   * the stage cannot infer it, because "over" and "around" render the same
   * layers and differ only in what the host meant.
   */
  arrangement?: 'over' | 'under' | 'around'
  /** The shape the layout is built around, when the host has one in mind. */
  format?: 'portrait' | 'landscape' | 'square'
  /**
   * The stage reads four custom properties a host may set on it: the safe
   * insets (`--gs-stage-inset-top` and the other three), which it otherwise
   * takes from `env()`; `--gs-stage-nav-height`, the height of the host's
   * own nav shell, which is what the interaction layer sits directly above;
   * and `--gs-stage-interaction-max`, how tall the interaction layer may grow,
   * 40% of the stage by default. The shell is the host's, so only the host
   * knows how tall it is; the stage measures nothing.
   *
   * `--gs-stage-nav-height` is the full height the shell stands, the
   * safe-area inset included. The stage pays that inset as padding inside the
   * nav layer so the shell's background reaches the glass, so a host that
   * declares only its bar's own height has declared a shell shorter than the
   * one on screen, and the interaction layer lands on it.
   *
   * Respect the device's safe areas. On by default: a stage is the component
   * most likely to be full-bleed on a phone, and a HUD under a notch is the
   * failure this prevents. A host that has already handled the insets itself
   * turns it off rather than paying them twice.
   */
  safeArea?: boolean
  /**
   * How the stage occupies the screen. GSUI-282, with Gamestage GS-537, whose
   * manifest `experience.layout` takes the same six words.
   *
   * Absent is the stage as it always was: it sets no size, and the scene or the
   * host's container gives it its box.
   *
   * - `screen`: fills the visible height (the dynamic viewport, so a phone's
   *   collapsing address bar never leaves a gap), holds its layers clear of the
   *   notch and home bar, and stops the page behind it scrolling, bouncing,
   *   pulling to refresh and zooming on a double tap. The frame is the device.
   * - `canvas`: as `screen`, with the content drawn at `design` size and scaled
   *   to fit, bars where the phone's shape differs. For games that need exact
   *   positions.
   * - `launch`: a card in the host page showing `preview` and one action,
   *   `launchLabel`. Opening it shows the game full screen over the page;
   *   closing it returns the reader to where they were, scroll and focus
   *   included. The recommended way to embed a game in an article.
   * - `card`: a fixed-proportion box inside a page that scrolls, with no
   *   scrolling inside it and swipes that don't fight the page. The fallback,
   *   for a host that can't open the game full screen.
   * - `page`: scrolls like a site, for long question lists and results.
   * - `sheet`: rises from the bottom over part of a host app, for one quick
   *   question.
   *
   * In the layouts where space is fixed (`screen`, `canvas`, `card`, `sheet`,
   * and an open `launch`), labels inside shrink before they wrap unless the host
   * or the component says otherwise, because a line gained is height a fixed
   * screen does not have.
   */
  fit?: StageFit
  /** For `canvas`: the size the game is drawn at, before it is scaled. Default 390 by 844. */
  design?: { width: number; height: number }
  /** For `launch`: what the card shows before the game opens. */
  preview?: React.ReactNode
  /** For `launch`: the one action on the card. Say what happens: "Play today's round". */
  launchLabel?: React.ReactNode
  /** The words for this instance: `stage.closeLabel` names the close control of an open launch. */
  strings?: StringsOverrides
  /** For `launch`: open or closed, when the host controls it. */
  open?: boolean
  /** For `launch`: told when the reader opens or closes the game. */
  onOpenChange?: (open: boolean) => void
  /** The layers. `Stage.Layer` children, in any order; the CSS stacks them. */
  children?: React.ReactNode
}

// The fit type, the fixed set and the context live in their own item so a
// component can read the layout without installing Stage. GSUI-282.
export { FIXED_FITS, useStageFit, useFixedSpace, type StageFit } from './fit'

/**
 * The page behind a full-screen stage, held still while the stage is mounted.
 *
 * On `<html>` rather than the stage, because what scrolls, bounces and pulls to
 * refresh is the document, not the stage. Counted, so two stages mounting and
 * one unmounting does not release the page from under the other.
 */
let holds = 0
function useHoldPage(active: boolean) {
  React.useEffect(() => {
    if (!active || typeof document === 'undefined') return
    holds += 1
    document.documentElement.setAttribute('data-gs-fit', 'screen')
    return () => {
      holds -= 1
      if (holds === 0) document.documentElement.removeAttribute('data-gs-fit')
    }
  }, [active])
}

/** The scale that fits `design` inside the stage's own box, kept current on resize. */
function useCanvasScale(active: boolean, design: { width: number; height: number }) {
  const ref = React.useRef<HTMLDivElement>(null)
  const [scale, setScale] = React.useState(1)
  React.useLayoutEffect(() => {
    const el = ref.current
    if (!active || !el || typeof ResizeObserver === 'undefined') return
    const measure = () => {
      const { width, height } = el.getBoundingClientRect()
      if (width > 0 && height > 0) setScale(Math.min(width / design.width, height / design.height))
    }
    measure()
    const observer = new ResizeObserver(measure)
    observer.observe(el)
    return () => observer.disconnect()
  }, [active, design.width, design.height])
  return { ref, scale }
}

/**
 * Focus held inside an open launch, Escape to close. Its own few lines rather
 * than Sheet's trap, because importing that installs Sheet and Button with it
 * and doubled the stage's weight for the one layout that needs a trap.
 */
function holdFocus(panel: HTMLElement, onEscape: () => void): () => void {
  const focusable = () =>
    [...panel.querySelectorAll<HTMLElement>('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])')].filter(
      (el) => !el.hasAttribute('disabled') && el.closest('[hidden]') === null,
    )
  focusable()[0]?.focus({ preventScroll: true })
  const onKey = (event: KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.preventDefault()
      onEscape()
      return
    }
    if (event.key !== 'Tab') return
    const items = focusable()
    const first = items[0]
    const last = items[items.length - 1]
    if (!first || !last) return
    if (event.shiftKey && document.activeElement === first) {
      event.preventDefault()
      last.focus()
    } else if (!event.shiftKey && document.activeElement === last) {
      event.preventDefault()
      first.focus()
    }
  }
  panel.addEventListener('keydown', onKey)
  return () => panel.removeEventListener('keydown', onKey)
}

const DEFAULT_DESIGN = { width: 390, height: 844 }
const SHRINK_FIRST = { labelFit: 'shrink' } as const

export function Stage({
  scene,
  arrangement = 'over',
  format,
  safeArea = true,
  fit,
  design = DEFAULT_DESIGN,
  preview,
  launchLabel,
  strings,
  open: openProp,
  onOpenChange,
  className,
  children,
  ...rest
}: StageProps) {
  const copy = useStrings(strings)
  const [openState, setOpenState] = React.useState(false)
  const open = fit === 'launch' ? (openProp ?? openState) : false
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (openProp === undefined) setOpenState(next)
      onOpenChange?.(next)
    },
    [openProp, onOpenChange],
  )

  const holdsScreen = fit === 'screen' || fit === 'canvas' || (fit === 'launch' && open)
  useHoldPage(holdsScreen)
  const canvas = useCanvasScale(fit === 'canvas', design)

  // A launch returns the reader to where they were: the scroll position and the
  // control they pressed, both put back when the game closes.
  const returnTo = React.useRef<{ scrollY: number; focus: Element | null } | null>(null)
  const rootRef = React.useRef<HTMLDivElement>(null)
  const openLaunch = () => {
    returnTo.current = { scrollY: window.scrollY, focus: document.activeElement }
    setOpen(true)
  }
  React.useEffect(() => {
    if (fit !== 'launch' || !open || !rootRef.current) return
    const release = holdFocus(rootRef.current, () => setOpen(false))
    return () => {
      release()
      const back = returnTo.current
      if (back) {
        window.scrollTo(0, back.scrollY)
        if (back.focus instanceof HTMLElement) back.focus.focus({ preventScroll: true })
      }
    }
  }, [fit, open, setOpen])

  const fixed = fit !== undefined && (FIXED_FITS.has(fit) || (fit === 'launch' && open))

  const layers = (
    <>
      {/*
        The scene goes first and in normal flow, so it gives the stage its box
        and every absolute layer resolves against it. Rendered only when the
        host passes one: an empty scene layer would be a zero-height block that
        contributes nothing and shows up in every selector counting layers.

        `{scene}` and nothing else. No wrapper inside, no ref, no measurement,
        no cloneElement: the moment the stage reads the scene it has an opinion
        about what a scene is, and the library's whole claim is that it does not.
      */}
      {scene !== undefined && scene !== null ? (
        <StageLayer layer="scene">{scene}</StageLayer>
      ) : null}
      {children}
    </>
  )

  // Fixed space prefers a smaller label to an extra line. A host's own
  // provider, or a component's own prop, still wins: this only fills a gap.
  const content = fixed ? <LabelFitDefaults settings={SHRINK_FIRST}>{layers}</LabelFitDefaults> : layers

  if (fit === 'launch' && !open) {
    return (
      <div
        {...rest}
        className={['gs-stage', className].filter(Boolean).join(' ')}
        data-gs-component="stage"
        data-gs-fit="launch"
      >
        <div className="gs-stage__preview">{preview}</div>
        <button type="button" className="gs-stage__launch gs-pressable gs-action-type" onClick={openLaunch}>
          {launchLabel}
        </button>
      </div>
    )
  }

  return (
    <StageFitProvider value={fit}>
      <div
        {...rest}
        ref={rootRef}
        className={['gs-stage', className].filter(Boolean).join(' ')}
        data-gs-component="stage"
        data-gs-stage={arrangement}
        data-gs-format={format}
        data-gs-safe-area={safeArea ? 'true' : undefined}
        data-gs-fit={fit}
        data-gs-open={fit === 'launch' && open ? 'true' : undefined}
        role={fit === 'launch' ? 'dialog' : rest.role}
        aria-modal={fit === 'launch' ? true : undefined}
      >
        {fit === 'launch' ? (
          <button
            type="button"
            className="gs-stage__close gs-pressable gs-action-type"
            aria-label={copy['stage.closeLabel']}
            onClick={() => setOpen(false)}
          >
            <CrossGlyph />
          </button>
        ) : null}
        {fit === 'canvas' ? (
          <div className="gs-stage__viewport" ref={canvas.ref}>
            <div
              className="gs-stage__canvas"
              style={
                {
                  '--gs-stage-canvas-width': `${design.width}px`,
                  '--gs-stage-canvas-height': `${design.height}px`,
                  '--gs-stage-canvas-scale': String(canvas.scale),
                } as React.CSSProperties
              }
            >
              {content}
            </div>
          </div>
        ) : (
          content
        )}
      </div>
    </StageFitProvider>
  )
}

Stage.Layer = StageLayer

/* Stage. Every value comes from a token; nothing here is a literal colour, and
   nothing here is a literal dimension either, because a stage that set its own
   dimensions would fight every host that embeds it.

   Two things this file deliberately does not do. It sets no width, no height
   and no aspect-ratio on the root: the scene in normal flow gives the stage its
   box, or the host's own container does. And it names no colour at all, not
   even a background, because the thing behind the layers is the host's scene
   and painting over it is the one failure the component exists to avoid.

   Specimen 5e is the layout reference, redlined: seven layers over a 390 by
   844 phone, with the inset each one sits at. design/twins/5e.json measures
   this file against it. */

.gs-stage {
  /* The containing block every absolute layer resolves against. That is the
     only thing the root does. */
  position: relative;
  /* Layers are stacked by z-index, and z-index is only meaningful inside a
     stacking context the stage owns. Without this a host's own `z-index: 10`
     somewhere up the tree reorders the library's layers. */
  isolation: isolate;
  /* The stage is the screen. Specimen 5e draws it clipped, and a layer that
     slides in from an edge should not paint outside the scene it belongs to. */
  overflow: hidden;
}

/* The insets a phone takes away. Named once here rather than repeated in every
   layer rule, and zero when the host says it has handled them itself. `env()`
   is a browser value, not a design decision, which is why it is not a token.

   `--gs-stage-nav-height` is the third thing a host tells the stage. The nav
   shell is the host's (specimen 5e: "the host owns scene AND nav shell"), so
   only the host knows how tall it is, and the interaction layer has to sit
   directly above it. A host with no nav leaves it at zero.

   `--gs-stage-interaction-max` is the fourth: how tall the interaction layer
   may grow, 40% of the stage by default. Declared with the interaction rule
   below rather than here, because it is that layer's cap and nothing else
   reads it. */
.gs-stage {
  --gs-stage-inset-top: 0px;
  --gs-stage-inset-bottom: 0px;
  --gs-stage-inset-left: 0px;
  --gs-stage-inset-right: 0px;
  --gs-stage-nav-height: 0px;
}

.gs-stage[data-gs-safe-area='true'] {
  --gs-stage-inset-top: env(safe-area-inset-top, 0px);
  --gs-stage-inset-bottom: env(safe-area-inset-bottom, 0px);
  --gs-stage-inset-left: env(safe-area-inset-left, 0px);
  --gs-stage-inset-right: env(safe-area-inset-right, 0px);
}

/* ------------------------------------------------------------ the scene -- */

/* In normal flow, so the host's scene gives the stage its box. Nothing about
   the scene is styled: no size, no background, no overflow, no transform. The
   layer exists to carry `data-gs-layer="scene"` and to sit at the bottom of the
   stack, and does not otherwise touch what is in it. */
.gs-stage__layer[data-gs-layer='scene'] {
  position: relative;
  z-index: 0;
}

/* ------------------------------------------------------ everything else -- */

/* Absolute, because the scene is the only thing in flow. Placement decides
   which edges are pinned; a layer with no placement covers the stage.

   Each edge sits at the device's own bite out of the screen or at the
   library's side inset, whichever is further in. Specimen 5e draws the HUD at
   the 44px the status bar takes and 10px in from each side, and the
   interaction zone 10px in from each side; 3j drew 14 and 5e supersedes it.
   Where there is no bite the inset keeps a HUD from lying flush against the
   glass. This used to be padding on top of the insets, which put every layer
   lower than drawn and made the edge a layer sat at a different fact from the
   edge a test could read. */
.gs-stage__layer:not([data-gs-layer='scene']) {
  position: absolute;
  top: max(var(--gs-stage-inset-top), var(--gs-space-gap));
  right: max(var(--gs-stage-inset-right), var(--gs-space-gap));
  bottom: max(var(--gs-stage-inset-bottom), var(--gs-space-gap));
  left: max(var(--gs-stage-inset-left), var(--gs-space-gap));
}

/* What sits behind the scene, what is asked to be read over it, and what
   celebrates over everything cover the whole stage, glass to glass: a backdrop
   with a margin is a picture frame, and confetti that stops 10px short of the
   edge is a box. Specimen 5e: "covering layers inset:0". */
.gs-stage__layer[data-gs-layer='behind'],
.gs-stage__layer[data-gs-layer='overlay'],
.gs-stage__layer[data-gs-layer='celebration'] {
  inset: 0;
}

/* The stacking order is the library's, which is why `data-gs-layer` is a closed
   set. Specimen 5e, bottom to top: scene, behind, hud, interaction, overlay,
   nav, celebration. A result plate lands over the choice grid it answers, and
   the nav stays reachable over both. No token names these; the request is in
   the contract. */
.gs-stage__layer[data-gs-layer='behind']      { z-index: -1; }
.gs-stage__layer[data-gs-layer='hud']         { z-index: 1; }
.gs-stage__layer[data-gs-layer='interaction'] { z-index: 2; }
.gs-stage__layer[data-gs-layer='overlay']     { z-index: 3; }
.gs-stage__layer[data-gs-layer='nav']         { z-index: 4; }
.gs-stage__layer[data-gs-layer='celebration'] { z-index: 5; }

/* A layer that sits at an edge is as big as what is in it, which is what makes
   `data-gs-pointer-events="auto"` safe on it: it can only swallow a press inside its
   own contents. Each placement releases the edges it is not pinned to. */
.gs-stage__layer[data-gs-placement='top']    { bottom: auto; }
.gs-stage__layer[data-gs-placement='bottom'] { top: auto; }
.gs-stage__layer[data-gs-placement='left']   { right: auto; }
.gs-stage__layer[data-gs-placement='right']  { left: auto; }

.gs-stage__layer[data-gs-placement='top-left']     { bottom: auto; right: auto; }
.gs-stage__layer[data-gs-placement='top-right']    { bottom: auto; left: auto; }
.gs-stage__layer[data-gs-placement='bottom-left']  { top: auto; right: auto; }
.gs-stage__layer[data-gs-placement='bottom-right'] { top: auto; left: auto; }

/* Centre is the one placement that covers the stage and still has to lay its
   contents out, so it keeps all four edges and centres what is in it. */
.gs-stage__layer[data-gs-placement='center'] {
  display: grid;
  place-items: center;
}

/* ------------------------------------------------------- the interaction -- */

/* The choice grid, the slider, the form: what the player answers with. It has
   one place, the bottom, whatever placement it is given, because a thumb
   reaches the bottom of a phone and the drawing puts it nowhere else. It sits
   directly above the nav shell, `space.inset` clear of it (5e: nav 96 tall,
   interaction bottom 110), or at the home indicator when there is no nav. It
   is 40% of the stage tall at most, so the scene stays the scene; a form
   longer than that scrolls inside the layer rather than growing over the HUD.

   The cap is `--gs-stage-interaction-max`, the fourth custom property a host
   may set, because 40% is right for the two-option round specimen 5e draws
   and too short for a four-option question plus its commit control on an 844
   phone: the layer scrolled and hid the control, which is the one thing a
   player must always be able to reach. A host raising it is trading scene for
   round, deliberately and in one place, rather than the library guessing. */
.gs-stage__layer[data-gs-layer='interaction'] {
  top: auto;
  bottom: max(var(--gs-stage-inset-bottom), calc(var(--gs-stage-nav-height) + var(--gs-space-inset)));
  max-block-size: var(--gs-stage-interaction-max, 40%);
  overflow-y: auto;
}

/* ---------------------------------------------------------------- the nav -- */

/* The nav bar spans the glass: side 0, bottom 0, and the home indicator's 34px
   is paid inside the shell as padding so the shell's own background reaches
   the bottom edge (5e: "nav · bottom · safe-area 34 · host-owned shell"). A
   nav placed in a corner keeps the ordinary inset, because a chip flush in a
   corner is a chip under a rounded corner. */
.gs-stage__layer[data-gs-layer='nav'][data-gs-placement='bottom'] {
  left: 0;
  right: 0;
  bottom: 0;
  padding-bottom: var(--gs-stage-inset-bottom);
}

/* ---------------------------------------------------------- the presses -- */

/* The pointer rule, as two lines. `data-gs-pointer-events` is what the component
   declares and this is the only place it becomes behaviour, so a browser test
   asserting the attribute is asserting the thing that is true. */
.gs-stage__layer[data-gs-pointer-events='none'] { pointer-events: none; }
.gs-stage__layer[data-gs-pointer-events='auto'] { pointer-events: auto; }

/* A covering layer passes presses through, and a control a host puts inside one
   anyway has to be reachable: an overlay with a Skip button is the case. The
   layer stays transparent and its direct children do not, which is the standard
   way round and the reason `data-gs-pointer-events` has two values rather than three.

   The obligation this puts on the host is real and is documented with the
   component: a direct child of a covering layer takes presses across whatever
   area it occupies, so a child stretched to `height: 100%` re-swallows the
   whole scene while the layer's attribute still reads `none`. Size the child to
   its content. A test asserting the attribute would pass over that, which is
   the gate describing what got built rather than what was meant. */
.gs-stage__layer[data-gs-pointer-events='none'] > * { pointer-events: auto; }

/* --------------------------------------------------------- composition -- */

/* There is no rule here for `hud`, for `nav` or for anything else the host puts
   in a layer, and that is the result worth recording rather than an omission.
   A layer is a block box with its edges pinned, so whatever goes in it lays
   itself out exactly as it does anywhere else and needs nothing from this file.
   The moment stage styled another component's class it would be writing a rule
   whose winner depends on which stylesheet the bundler put last: stage depends
   on no component, so it has no import-order claim on any of them.

   Nothing paints on scene pixels except floating depth. The rule is the
   contents', not this file's: a HUD chip wears `depth.floating` and nothing
   else in a layer carries a background, so the scene shows through everywhere
   a component is not. */

/* -------------------------------------------------------------- fit -- */

/* How the stage occupies the screen, GSUI-282. Every rule below is keyed on
   `data-gs-fit`, so a stage with no fit is exactly the stage above: it sets no
   size and the scene or the host gives it its box. */

/* The page behind a full-screen stage holds still. On <html> because the
   document is what scrolls, bounces and pulls to refresh. */
html[data-gs-fit='screen'],
html[data-gs-fit='screen'] body {
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}

/* Screen, canvas and an open launch: the frame is the device. `dvh`, so the
   phone's collapsing address bar never leaves a band at the foot, with `vh`
   first for a browser that has no `dvh`. `manipulation` keeps taps and pans
   and drops double-tap zoom. */
.gs-stage[data-gs-fit='screen'],
.gs-stage[data-gs-fit='canvas'],
.gs-stage[data-gs-fit='launch'][data-gs-open='true'] {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100vh;
  height: 100dvh;
  overscroll-behavior: none;
  touch-action: manipulation;
  background: var(--gs-color-surface);
}

.gs-stage[data-gs-fit='launch'][data-gs-open='true'] {
  z-index: 2147483000;
}

/* Canvas: the game is drawn at its design size and scaled to the device,
   centred, with bars of the stage's own surface where the shapes differ. */
.gs-stage__viewport {
  position: absolute;
  inset: var(--gs-stage-inset-top) var(--gs-stage-inset-right) var(--gs-stage-inset-bottom)
    var(--gs-stage-inset-left);
  display: grid;
  place-items: center;
  overflow: hidden;
}

.gs-stage__canvas {
  position: relative;
  width: var(--gs-stage-canvas-width);
  height: var(--gs-stage-canvas-height);
  flex: none;
  transform: scale(var(--gs-stage-canvas-scale, 1));
  transform-origin: center center;
}

/* Card: a fixed-proportion box in a page that scrolls. Nothing scrolls inside
   it, and a swipe that reaches its edge stops there rather than scrolling the
   article. 9:16 unless the host says otherwise. */
.gs-stage[data-gs-fit='card'] {
  width: 100%;
  aspect-ratio: var(--gs-stage-aspect, 9 / 16);
  max-height: 90vh;
  overscroll-behavior: contain;
  touch-action: manipulation;
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface);
}

/* Sheet: rises from the foot over part of a host app. */
.gs-stage[data-gs-fit='sheet'] {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  height: var(--gs-stage-sheet-height, 60dvh);
  max-height: 90dvh;
  overscroll-behavior: contain;
  border-radius: var(--gs-radius-lg) var(--gs-radius-lg) 0 0;
  background: var(--gs-color-surface);
}

/* Page: the stage grows with its content and the document scrolls. */
.gs-stage[data-gs-fit='page'] {
  min-height: 100vh;
  min-height: 100dvh;
  overflow: visible;
}

/* Launch, closed: a card in the host page with a preview and one action. */
.gs-stage[data-gs-fit='launch']:not([data-gs-open='true']) {
  display: grid;
  gap: var(--gs-space-3);
  padding: var(--gs-space-4);
  border-radius: var(--gs-radius-lg);
  background: var(--gs-color-surface);
  color: var(--gs-color-ink);
}

.gs-stage__launch {
  min-height: var(--gs-size-touch-min);
  padding: var(--gs-space-3) var(--gs-space-4);
  border: 0;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-interactive);
  color: var(--gs-color-on-accent);
  font: inherit;
  font-weight: var(--gs-type-action-font-weight);
  cursor: pointer;
}

/* Launch, open: one way back, always in the same corner, above every layer. */
.gs-stage__close {
  position: absolute;
  top: calc(var(--gs-stage-inset-top) + var(--gs-space-3));
  right: calc(var(--gs-stage-inset-right) + var(--gs-space-3));
  z-index: 10;
  width: var(--gs-size-touch-min);
  height: var(--gs-size-touch-min);
  border: 0;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-surface-raised);
  color: var(--gs-color-ink);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  cursor: pointer;
}
